const app = express();
const uploadRoot=path.resolve('storage/uploads');
await fs.mkdir(uploadRoot,{recursive:true});
const acceptedMimeTypes=new Set(['image/jpeg','image/png','image/webp','application/pdf']);
const upload=multer({
  storage:multer.diskStorage({destination:uploadRoot,filename:(_request,file,callback)=>callback(null,`${crypto.randomUUID()}${path.extname(file.originalname).toLowerCase().slice(0,10)}`)}),
  limits:{fileSize:8*1024*1024,files:5},
  fileFilter:(_request,file,callback)=>callback(null,acceptedMimeTypes.has(file.mimetype)),
});
app.disable('x-powered-by');
app.use(helmet());
app.use(cors({ origin:(origin,callback)=>callback(null,!origin||origin===config.frontendUrl), credentials: true }));
