app.use((error:unknown,_request:express.Request,response:express.Response,next:express.NextFunction)=>{if(error instanceof SyntaxError&&'body' in error)return response.status(400).json({error:'Malformed JSON request.'});next(error);});
app.use((request,response,next)=>{const requestId=crypto.randomUUID();response.setHeader('X-Request-Id',requestId);const started=Date.now();response.on('finish',()=>{void pool.query('INSERT INTO structured_logs(log_level,log_type,message,context_json,request_id) VALUES(?,?,?,?,?)',[response.statusCode>=500?'error':response.statusCode>=400?'warn':'info','application',`${request.method} ${request.path}`,JSON.stringify({status:response.statusCode,durationMs:Date.now()-started,ip:request.ip}),requestId]).catch(()=>undefined);});next();});
