const roleToClient = (role: string) => ({ CITIZEN:'citizen', STAFF:'staff', SUPERVISOR:'supervisor', ADMINISTRATOR:'admin', NATIONAL_ADMIN:'super-admin' }[role] || 'citizen');
const publicUser = (user: AuthUser) => ({ id:user.id,fullName:user.fullName,email:user.email,phone:user.phone,role:roleToClient(user.role),roleLabel:user.role.split('_').map(part=>part[0]+part.slice(1).toLowerCase()).join(' '),municipality:user.municipality||null,municipalityId:user.municipalityId||null,district:user.district||null,profileImageUrl:user.profileUploadId?`/api/uploads/${user.profileUploadId}`:null });
const audit = async (userId: number | null, action: string, request: express.Request, entityType?: string, entityId?: number, metadata?: unknown) => {
  await pool.query('INSERT INTO audit_logs (user_id,action,entity_type,entity_id,ip_address,metadata_json) VALUES (?,?,?,?,?,?)',
    [userId, action, entityType || null, entityId || null, request.ip, metadata ? JSON.stringify(metadata) : null]);
};
const csvCell=(value:unknown)=>`"${String(value??'').replace(/"/g,'""')}"`;
const pdfEscape=(value:string)=>value.replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[^\x20-\x7E]/g,'?');
const htmlEscape=(value:unknown)=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]!));
const createTextPdf=(title:string,lines:string[])=>{
  const pages:Array<string[]>=[];for(let index=0;index<lines.length;index+=42)pages.push(lines.slice(index,index+42));if(!pages.length)pages.push(['No records found.']);
  const objects:string[]=[];const add=(body:string)=>{objects.push(body);return objects.length;};
  const catalog=add('');const pagesId=add('');const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');const pageIds:number[]=[];
  for(const [pageIndex,pageLines] of pages.entries()){const commands=[`BT /F1 14 Tf 50 790 Td (${pdfEscape(title)}) Tj`,`0 -22 Td /F1 8 Tf (${pdfEscape(`Page ${pageIndex+1} of ${pages.length}`)}) Tj`,...pageLines.map(line=>`0 -16 Td (${pdfEscape(line.slice(0,125))}) Tj`),'ET'].join('\n');const content=add(`<< /Length ${Buffer.byteLength(commands)} >>\nstream\n${commands}\nendstream`);pageIds.push(add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${content} 0 R >>`));}
  objects[catalog-1]=`<< /Type /Catalog /Pages ${pagesId} 0 R >>`;objects[pagesId-1]=`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`;
  let output='%PDF-1.4\n';const offsets=[0];objects.forEach((body,index)=>{offsets.push(Buffer.byteLength(output));output+=`${index+1} 0 obj\n${body}\nendobj\n`;});const xref=Buffer.byteLength(output);output+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(offset=>String(offset).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(output);
};
const createReportPdf=(rows:any[],exportedBy:string,filters:string)=>{
  const pageRows=18,pages:Array<any[]>=[];for(let index=0;index<rows.length;index+=pageRows)pages.push(rows.slice(index,index+pageRows));if(!pages.length)pages.push([]);
  const objects:string[]=[];const add=(body:string)=>{objects.push(body);return objects.length;};const catalog=add(''),pagesId=add(''),regular=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'),bold=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'),pageIds:number[]=[];
  const cellWidths=[82,174,92,60,65,72],headers=['Reference','Incident','District','Priority','Status','Date'];
  const truncate=(value:unknown,max:number)=>{const text=String(value??'');return text.length>max?`${text.slice(0,max-1)}...`:text;};
  pages.forEach((page,pageIndex)=>{const command:string[]=['0.106 0.369 0.125 rg 0 806 595 36 re f','0.039 0.247 0.353 rg 0 0 595 38 re f','0.263 0.627 0.278 rg 0 800 595 6 re f'];
    command.push(`BT /F2 18 Tf 0.106 0.369 0.125 rg 36 766 Td (${pdfEscape('ECOCLEAN SL')}) Tj ET`,`BT /F2 13 Tf 0.05 0.05 0.05 rg 36 744 Td (${pdfEscape('Environmental Incident Register')}) Tj ET`,`BT /F1 8 Tf 0.25 0.25 0.25 rg 36 727 Td (${pdfEscape(`Sierra Leone | Generated ${new Date().toLocaleString('en-SL',{timeZone:'Africa/Freetown'})}`)}) Tj ET`);
    command.push('0.95 0.98 0.95 rg 36 670 523 42 re f','0.75 0.85 0.76 RG 36 670 523 42 re S',`BT /F2 8 Tf 0.106 0.369 0.125 rg 46 696 Td (${pdfEscape(`AUTHORIZED EXPORT: ${exportedBy}`)}) Tj ET`,`BT /F1 8 Tf 0.20 0.20 0.20 rg 46 680 Td (${pdfEscape(`Scope: Sierra Leone | Filters: ${filters} | Records: ${rows.length}`)}) Tj ET`);
    let y=640,x=25;command.push('0.039 0.247 0.353 rg 25 640 545 24 re f');cellWidths.forEach((width,index)=>{command.push(`BT /F2 7 Tf 1 1 1 rg ${x+4} 648 Td (${headers[index]}) Tj ET`);x+=width;});y-=24;
    page.forEach((row,rowIndex)=>{x=25;const fill=rowIndex%2===0?'0.97 0.98 0.97':'1 1 1';command.push(`${fill} rg 25 ${y-22} 545 22 re f`,'0.78 0.82 0.79 RG 25 '+(y-22)+' 545 22 re S');const values=[truncate(row.reference,15),truncate(row.title,31),truncate(row.district||row.municipality||'Unassigned',16),truncate(row.priority,10),truncate(row.status,11),new Date(row.created_at).toLocaleDateString('en-SL')];values.forEach((value,index)=>{command.push(`BT /F1 6.5 Tf 0.10 0.10 0.10 rg ${x+4} ${y-9} Td (${pdfEscape(value)}) Tj ET`);x+=cellWidths[index];});y-=22;});
    command.push('0.106 0.369 0.125 rg 36 104 523 18 re f','BT /F2 7 Tf 1 1 1 rg 240 110 Td (OTHER COMMENTS / AUTHORIZATION) Tj ET','0.65 0.70 0.66 RG 36 82 523 1 re f','0.65 0.70 0.66 RG 36 62 523 1 re f','BT /F1 7 Tf 0.25 0.25 0.25 rg 36 45 Td (Prepared by: ____________________) Tj ET','BT /F1 7 Tf 0.25 0.25 0.25 rg 330 45 Td (Approved by: ____________________) Tj ET',`BT /F1 7 Tf 1 1 1 rg 36 14 Td (${pdfEscape('ECOCLEAN SL - Smart Waste Management & Environmental Intelligence Platform')}) Tj ET`,`BT /F1 7 Tf 1 1 1 rg 520 14 Td (${pageIndex+1}/${pages.length}) Tj ET`);
    const commands=command.join('\n'),content=add(`<< /Length ${Buffer.byteLength(commands)} >>\nstream\n${commands}\nendstream`);pageIds.push(add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${regular} 0 R /F2 ${bold} 0 R >> >> /Contents ${content} 0 R >>`));});
  objects[catalog-1]=`<< /Type /Catalog /Pages ${pagesId} 0 R >>`;objects[pagesId-1]=`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`;let output='%PDF-1.4\n';const offsets=[0];objects.forEach((body,index)=>{offsets.push(Buffer.byteLength(output));output+=`${index+1} 0 obj\n${body}\nendobj\n`;});const xref=Buffer.byteLength(output);output+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(offset=>String(offset).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(output);
};
const createOfficeHtml=(rows:any[],exportedBy:string,filters:string,mode:'word'|'excel')=>`<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4 landscape;margin:18mm}body{font-family:Arial,sans-serif;color:#202020;margin:0}.top{height:10px;background:linear-gradient(90deg,#0A3F5A 0 50%,#2E7D32 50%)}h1{text-align:center;margin:22px 0 6px;color:#1B5E20;font-size:24px}.sub{text-align:center;color:#666;font-size:11px;margin-bottom:18px}.meta{width:100%;border-collapse:collapse;margin-bottom:16px}.meta td{border:1px solid #b8c2bb;padding:7px;font-size:10px}.meta strong{color:#1B5E20}.data{width:100%;border-collapse:collapse;table-layout:fixed}.data th{background:#0A3F5A;color:white;border:1px solid #fff;padding:7px;font-size:9px}.data td{border:1px solid #aeb8b1;padding:6px;font-size:8px;vertical-align:top;word-wrap:break-word}.data tr:nth-child(even){background:#f1f7f2}.comments{margin-top:18px;background:#2E7D32;color:#fff;text-align:center;padding:6px;font-size:10px;font-weight:bold}.line{border-bottom:1px solid #999;height:22px}.sign{width:100%;margin-top:20px;font-size:9px}.footer{margin-top:24px;background:#0A3F5A;color:#fff;padding:12px;font-size:8px;display:flex;justify-content:space-between}</style></head><body><div class="top"></div><h1>ECOCLEAN SL Environmental Incident Register</h1><div class="sub">Smart Waste Management & Environmental Intelligence Platform - Sierra Leone</div><table class="meta"><tr><td><strong>Prepared By:</strong> ${htmlEscape(exportedBy)}</td><td><strong>Generated:</strong> ${htmlEscape(new Date().toLocaleString('en-SL',{timeZone:'Africa/Freetown'}))}</td></tr><tr><td><strong>Scope:</strong> Sierra Leone</td><td><strong>Filters:</strong> ${htmlEscape(filters)}</td></tr><tr><td><strong>Total Records:</strong> ${rows.length}</td><td><strong>Format:</strong> ${mode==='excel'?'Excel Spreadsheet':'Microsoft Word'}</td></tr></table><table class="data"><thead><tr>${['Reference','Incident','Description','Category','Priority','Status','Citizen','Municipality','District','Ward / Zone','Location','Created'].map(value=>`<th>${value}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${[row.reference,row.title,row.description,row.category,row.priority,row.status,row.citizen,row.municipality,row.district,[row.ward,row.zone].filter(Boolean).join(' / '),row.address,new Date(row.created_at).toLocaleDateString('en-SL')].map(value=>`<td>${htmlEscape(value)}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="comments">OTHER COMMENTS / AUTHORIZATION</div><div class="line"></div><div class="line"></div><table class="sign"><tr><td>Prepared by: ______________________________</td><td>Approved by: ______________________________</td></tr></table><div class="footer"><span>ECOCLEAN SL</span><span>Official operational export - generated from authenticated MariaDB records</span></div></body></html>`;

const createExcelWorkbook=async(rows:any[],exportedBy:string,filters:string)=>{const workbook=new ExcelJS.Workbook();workbook.creator='ECOCLEAN SL';const sheet=workbook.addWorksheet('Incident Register',{pageSetup:{orientation:'landscape',fitToPage:true,fitToWidth:1}});sheet.mergeCells('A1:L1');Object.assign(sheet.getCell('A1'),{value:'ECOCLEAN SL — ENVIRONMENTAL INCIDENT REGISTER',font:{bold:true,color:{argb:'FFFFFFFF'},size:18},alignment:{horizontal:'center'},fill:{type:'pattern',pattern:'solid',fgColor:{argb:'FF0A3F5A'}}});sheet.mergeCells('A2:L2');sheet.getCell('A2').value='Smart Waste Management & Environmental Intelligence Platform • Sierra Leone';sheet.getCell('A2').alignment={horizontal:'center'};sheet.getCell('A2').font={italic:true,color:{argb:'FF1B5E20'}};sheet.getCell('A4').value=`Prepared by: ${exportedBy}`;sheet.getCell('E4').value=`Generated: ${new Date().toLocaleString('en-SL',{timeZone:'Africa/Freetown'})}`;sheet.getCell('I4').value='Scope: Sierra Leone';sheet.getCell('A5').value=`Filters: ${filters}`;sheet.getCell('E5').value=`Total records: ${rows.length}`;const headers=['Reference','Incident','Description','Category','Priority','Status','Citizen','Municipality','District','Ward / Zone','Location','Created'];sheet.addRow([]);const heading=sheet.addRow(headers);heading.eachCell(cell=>{cell.font={bold:true,color:{argb:'FFFFFFFF'}};cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF0A3F5A'}};cell.alignment={horizontal:'center',vertical:'middle',wrapText:true};});rows.forEach((row,index)=>{const current=sheet.addRow([row.reference,row.title,row.description,row.category,row.priority,row.status,row.citizen,row.municipality,row.district,[row.ward,row.zone].filter(Boolean).join(' / '),row.address,new Date(row.created_at)]);current.eachCell(cell=>{cell.alignment={vertical:'top',wrapText:true};cell.border={top:{style:'thin',color:{argb:'FFB8C2BB'}},left:{style:'thin',color:{argb:'FFB8C2BB'}},bottom:{style:'thin',color:{argb:'FFB8C2BB'}},right:{style:'thin',color:{argb:'FFB8C2BB'}}};if(index%2)cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF1F7F2'}};});current.getCell(12).numFmt='dd-mmm-yyyy';});[15,25,40,18,12,14,22,24,20,20,32,15].forEach((width,index)=>sheet.getColumn(index+1).width=width);sheet.views=[{state:'frozen',ySplit:7}];sheet.autoFilter='A7:L7';return Buffer.from(await workbook.xlsx.writeBuffer());};
const wordTableCell=(value:unknown,header=false)=>new TableCell({shading:header?{type:ShadingType.CLEAR,fill:'0A3F5A'}:undefined,children:[new Paragraph({children:[new TextRun({text:String(value??''),bold:header,color:header?'FFFFFF':'202020',size:header?18:16})]})]});
const createWordDocument=async(rows:any[],exportedBy:string,filters:string)=>{const border={style:BorderStyle.SINGLE,size:4,color:'B8C2BB'};const dataTable=new Table({width:{size:100,type:WidthType.PERCENTAGE},borders:{top:border,bottom:border,left:border,right:border,insideHorizontal:border,insideVertical:border},rows:[new TableRow({tableHeader:true,children:['Reference','Incident','Category','Priority','Status','District','Location','Created'].map(value=>wordTableCell(value,true))}),...rows.map(row=>new TableRow({children:[row.reference,row.title,row.category,row.priority,row.status,row.district,row.address,new Date(row.created_at).toLocaleDateString('en-SL')].map(value=>wordTableCell(value))}))]});const document=new Document({creator:'ECOCLEAN SL',title:'Environmental Incident Register',sections:[{children:[new Paragraph({alignment:AlignmentType.CENTER,shading:{type:ShadingType.CLEAR,fill:'0A3F5A'},children:[new TextRun({text:'ECOCLEAN SL',bold:true,color:'FFFFFF',size:36})]}),new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:'ENVIRONMENTAL INCIDENT REGISTER',bold:true,color:'1B5E20',size:28})]}),new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:'Smart Waste Management & Environmental Intelligence Platform • Sierra Leone',italics:true})]}),new Table({width:{size:100,type:WidthType.PERCENTAGE},rows:[new TableRow({children:[wordTableCell(`Prepared by: ${exportedBy}`),wordTableCell(`Generated: ${new Date().toLocaleString('en-SL',{timeZone:'Africa/Freetown'})}`)]}),new TableRow({children:[wordTableCell(`Filters: ${filters}`),wordTableCell(`Records: ${rows.length} • Sierra Leone`)]})]}),new Paragraph(''),dataTable,new Paragraph(''),new Paragraph({alignment:AlignmentType.CENTER,shading:{type:ShadingType.CLEAR,fill:'2E7D32'},children:[new TextRun({text:'OTHER COMMENTS / AUTHORIZATION',bold:true,color:'FFFFFF'})]}),new Paragraph('________________________________________________________________________________'),new Paragraph('________________________________________________________________________________'),new Paragraph('Prepared by: _________________________        Approved by: _________________________'),new Paragraph({alignment:AlignmentType.CENTER,shading:{type:ShadingType.CLEAR,fill:'0A3F5A'},children:[new TextRun({text:'ECOCLEAN SL • Official authenticated operational export',bold:true,color:'FFFFFF'})]})]}]});return Buffer.from(await Packer.toBuffer(document));};

app.get('/api/reports/export-professional',authenticate,authorize('SUPERVISOR','ADMINISTRATOR'),async(request,response)=>{
  const parsed=z.object({format:z.enum(['csv','pdf','xlsx','docx','xls','doc','json','geojson']).default('pdf'),dateRange:z.enum(['all','today','week','quarter']).default('all'),status:z.string().max(40).optional(),priority:z.string().max(40).optional()}).safeParse(request.query);
  if(!parsed.success)return response.status(422).json({error:'Invalid export parameters.'});
  const where=['r.deleted_at IS NULL'],params:any[]=[];
  if(parsed.data.dateRange==='today')where.push('r.created_at>=DATE_SUB(NOW(),INTERVAL 1 DAY)');
  if(parsed.data.dateRange==='week')where.push('r.created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)');
  if(parsed.data.dateRange==='quarter')where.push('r.created_at>=DATE_SUB(NOW(),INTERVAL 3 MONTH)');
  if(parsed.data.status&&parsed.data.status!=='all'){where.push('r.status=?');params.push(parsed.data.status.toLowerCase().replace(/ /g,'_'));}
  if(parsed.data.priority&&parsed.data.priority!=='all'){where.push('r.priority=?');params.push(parsed.data.priority.toLowerCase());}
  if(request.authUser!.role==='SUPERVISOR'){
    const [scope]=await pool.query<any[]>('SELECT municipality_id,district_id FROM users WHERE id=?',[request.authUser!.id]);
    if(!scope[0]||(!scope[0].municipality_id&&!scope[0].district_id))return response.status(403).json({error:'Supervisor jurisdiction is not configured.'});
    where.push('(r.municipality_id=? OR r.district_id=?)');params.push(scope[0].municipality_id||0,scope[0].district_id||0);
  }
  const [rows]=await pool.query<any[]>(`SELECT r.reference,r.title,r.description,r.category,r.priority,r.status,r.latitude,r.longitude,r.address,r.created_at,r.updated_at,u.full_name citizen,u.email citizen_email,m.name municipality,d.name district,w.name ward,z.name zone FROM reports r JOIN users u ON u.id=r.citizen_id LEFT JOIN municipalities m ON m.id=r.municipality_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN wards w ON w.id=r.ward_id LEFT JOIN zones z ON z.id=r.zone_id WHERE ${where.join(' AND ')} ORDER BY r.created_at DESC`,params);
  const stamp=new Date().toISOString().slice(0,10),base=`ecoclean_sl_incident_register_${stamp}`,filters=[parsed.data.dateRange,parsed.data.status,parsed.data.priority].filter(Boolean).join(' / ')||'All records';
  await audit(request.authUser!.id,'reports.professional_exported',request,'report',undefined,{format:parsed.data.format,dateRange:parsed.data.dateRange,records:rows.length});
  if(parsed.data.format==='json')return response.attachment(`${base}.json`).type('application/json').send(JSON.stringify({title:'ECOCLEAN SL Environmental Incident Register',scope:'Sierra Leone',exportedAt:new Date().toISOString(),exportedBy:request.authUser!.fullName,records:rows},null,2));
  if(parsed.data.format==='geojson'){const features=rows.filter(row=>row.latitude!=null&&row.longitude!=null).map(row=>({type:'Feature',geometry:{type:'Point',coordinates:[Number(row.longitude),Number(row.latitude)]},properties:Object.fromEntries(Object.entries(row).filter(([key])=>!['latitude','longitude'].includes(key)))}));return response.attachment(`${base}.geojson`).type('application/geo+json').send(JSON.stringify({type:'FeatureCollection',name:'ECOCLEAN SL Environmental Incidents',features},null,2));}
  const headers=['Reference','Title','Description','Category','Priority','Status','Citizen','Citizen Email','Municipality','District','Ward','Zone','Latitude','Longitude','Address','Created','Updated'];
  const values=rows.map(row=>[row.reference,row.title,row.description,row.category,row.priority,row.status,row.citizen,row.citizen_email,row.municipality,row.district,row.ward,row.zone,row.latitude,row.longitude,row.address,row.created_at,row.updated_at]);
  if(parsed.data.format==='csv'){const csv='\uFEFF'+[headers,...values].map(record=>record.map(csvCell).join(',')).join('\r\n');return response.attachment(`${base}.csv`).type('text/csv; charset=utf-8').send(csv);}
  if(parsed.data.format==='xlsx')return response.attachment(`${base}.xlsx`).type('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet').send(await createExcelWorkbook(rows,request.authUser!.fullName,filters));
  if(parsed.data.format==='docx')return response.attachment(`${base}.docx`).type('application/vnd.openxmlformats-officedocument.wordprocessingml.document').send(await createWordDocument(rows,request.authUser!.fullName,filters));
  if(parsed.data.format==='xls')return response.attachment(`${base}.xls`).type('application/vnd.ms-excel; charset=utf-8').send(createOfficeHtml(rows,request.authUser!.fullName,filters,'excel'));
  if(parsed.data.format==='doc')return response.attachment(`${base}.doc`).type('application/msword; charset=utf-8').send(createOfficeHtml(rows,request.authUser!.fullName,filters,'word'));
  return response.attachment(`${base}.pdf`).type('application/pdf').send(createReportPdf(rows,request.authUser!.fullName,filters));
});

const jurisdictionClause=(user:AuthUser,alias='r')=>user.role==='ADMINISTRATOR'?{sql:'1=1',params:[]}:user.role==='CITIZEN'?{sql:`${alias}.citizen_id=?`,params:[user.id]}:user.role==='SUPERVISOR'?{sql:`(${alias}.municipality_id=? OR ${alias}.district_id=?)`,params:[user.municipalityId||0,(user as any).districtId||0]}:{sql:'1=1',params:[]};

app.get('/api/reports-scoped',authenticate,async(request,response)=>{
  const user=request.authUser!;
  if(user.role==='STAFF'){
    const [scope]=await pool.query<any[]>('SELECT district_id FROM users WHERE id=?',[user.id]);
    const [rows]=await pool.query('SELECT r.id,r.reference,r.title,r.description,r.category,r.priority,r.status,r.latitude,r.longitude,r.address,r.municipality_id,r.district_id,r.ward_id,r.zone_id,r.created_at,m.name municipality,d.name district,w.name ward,z.name zone,EXISTS(SELECT 1 FROM tasks t WHERE t.report_id=r.id AND t.assigned_to=?) assigned_to_me FROM reports r LEFT JOIN municipalities m ON m.id=r.municipality_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN wards w ON w.id=r.ward_id LEFT JOIN zones z ON z.id=r.zone_id WHERE r.deleted_at IS NULL AND r.district_id=? ORDER BY r.created_at DESC LIMIT 100',[user.id,scope[0]?.district_id||0]);
    return response.json({data:rows});
  }
  if(user.role==='SUPERVISOR'){
    const [scope]=await pool.query<any[]>('SELECT municipality_id,district_id FROM users WHERE id=?',[user.id]);
    const [rows]=await pool.query('SELECT r.*,m.name municipality,d.name district,w.name ward,z.name zone FROM reports r LEFT JOIN municipalities m ON m.id=r.municipality_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN wards w ON w.id=r.ward_id LEFT JOIN zones z ON z.id=r.zone_id WHERE r.deleted_at IS NULL AND (r.municipality_id=? OR r.district_id=?) ORDER BY r.created_at DESC LIMIT 100',[scope[0]?.municipality_id||0,scope[0]?.district_id||0]);
    return response.json({data:rows});
  }
  const [rows]=await pool.query(`SELECT r.*,m.name municipality,d.name district,w.name ward,z.name zone FROM reports r LEFT JOIN municipalities m ON m.id=r.municipality_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN wards w ON w.id=r.ward_id LEFT JOIN zones z ON z.id=r.zone_id WHERE r.deleted_at IS NULL ${user.role==='CITIZEN'?'AND r.citizen_id=?':''} ORDER BY r.created_at DESC LIMIT 100`,user.role==='CITIZEN'?[user.id]:[]);
  response.json({data:rows});
});

