app.post('/api/reports-operational',authenticate,authorize('CITIZEN'),async(request,response)=>{
  const parsed=z.object({title:z.string().min(3),description:z.string().min(10),category:z.string().min(2),latitude:z.number().min(-90).max(90),longitude:z.number().min(-180).max(180),address:z.string().optional(),districtName:z.string().min(2),municipalityName:z.string().min(2),wardName:z.string().optional(),zoneName:z.string().optional()}).safeParse(request.body);
  if(!parsed.success)return response.status(422).json({error:'Invalid report details.',fields:parsed.error.flatten().fieldErrors});
  const [districts]=await pool.query<any[]>(`SELECT d.id district_id,d.municipality_id FROM districts d LEFT JOIN municipalities m ON m.id=d.municipality_id WHERE d.name=? AND (m.name=? OR ? LIKE CONCAT('%',m.name,'%') OR m.name LIKE CONCAT('%',?,'%')) LIMIT 1`,[parsed.data.districtName,parsed.data.municipalityName,parsed.data.municipalityName,parsed.data.municipalityName]);
  if(!districts[0])return response.status(422).json({error:'Select a valid Sierra Leone district and municipality.'});
  const reference=`ECO-${new Date().getFullYear()}-${crypto.randomInt(100000,999999)}`;
  const [result]=await pool.query<any>('INSERT INTO reports(reference,citizen_id,municipality_id,district_id,title,description,category,latitude,longitude,address) VALUES(?,?,?,?,?,?,?,?,?,?)',[reference,request.authUser!.id,districts[0].municipality_id,districts[0].district_id,parsed.data.title,parsed.data.description,parsed.data.category,parsed.data.latitude,parsed.data.longitude,parsed.data.address||null]);
  await pool.query('INSERT INTO report_history(report_id,actor_user_id,action,to_status,snapshot_json) VALUES(?,?,?,?,?)',[result.insertId,request.authUser!.id,'created','pending',JSON.stringify(parsed.data)]);
  await pool.query("INSERT INTO notifications(user_id,type,title,body,data_json) VALUES(?,'report_created','Report Logged Successfully',?,?)",[request.authUser!.id,`${reference} is pending supervisor review.`,JSON.stringify({reportId:result.insertId})]);
  await pool.query(`INSERT INTO notifications(user_id,type,title,body,data_json) SELECT u.id,'new_report','New Citizen Report',?,? FROM users u JOIN roles role ON role.id=u.role_id WHERE u.status='active' AND role.code IN ('SUPERVISOR','ADMINISTRATOR') AND (role.code='ADMINISTRATOR' OR u.district_id=? OR u.municipality_id=?)`,[`${reference}: ${parsed.data.title}`,JSON.stringify({reportId:result.insertId,district:parsed.data.districtName}),districts[0].district_id,districts[0].municipality_id]);
  await audit(request.authUser!.id,'report.created',request,'report',result.insertId,{district:parsed.data.districtName});
  response.status(201).json({data:{id:result.insertId,reference,...parsed.data,status:'pending'}});
});

app.post('/api/tasks-operational',authenticate,authorize('SUPERVISOR','ADMINISTRATOR'),async(request,response)=>{
  const parsed=z.object({reportId:z.number().int(),assignedTo:z.number().int(),title:z.string().min(3),description:z.string().optional(),priority:z.enum(['low','medium','high','critical']).default('medium'),dueAt:z.string().datetime().optional()}).safeParse(request.body);
  if(!parsed.success)return response.status(422).json({error:'Invalid task assignment.',fields:parsed.error.flatten().fieldErrors});
  const [staff]=await pool.query<any[]>(`SELECT u.id,u.district_id,u.municipality_id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.status='active' AND r.code='STAFF' LIMIT 1`,[parsed.data.assignedTo]);
  const [reports]=await pool.query<any[]>('SELECT id,citizen_id,district_id,municipality_id,status FROM reports WHERE id=? AND deleted_at IS NULL',[parsed.data.reportId]);
  if(!staff[0]||!reports[0])return response.status(422).json({error:'Select an active staff member and valid report.'});
  if(staff[0].district_id!==reports[0].district_id&&staff[0].municipality_id!==reports[0].municipality_id)return response.status(403).json({error:'Staff member is outside the report jurisdiction.'});
  if(request.authUser!.role==='SUPERVISOR'&&request.authUser!.municipalityId!==reports[0].municipality_id)return response.status(403).json({error:'Report is outside your jurisdiction.'});
  const [duplicate]=await pool.query<any[]>("SELECT id FROM tasks WHERE report_id=? AND status NOT IN ('cancelled','rejected') LIMIT 1",[parsed.data.reportId]);if(duplicate[0])return response.status(409).json({error:'This report already has an active task.'});
  const reference=`TASK-${new Date().getFullYear()}-${crypto.randomInt(100000,999999)}`;
  const [result]=await pool.query<any>('INSERT INTO tasks(reference,report_id,assigned_to,assigned_by,title,description,priority,due_at) VALUES(?,?,?,?,?,?,?,?)',[reference,parsed.data.reportId,parsed.data.assignedTo,request.authUser!.id,parsed.data.title,parsed.data.description||null,parsed.data.priority,parsed.data.dueAt?new Date(parsed.data.dueAt):null]);
  await pool.query("UPDATE reports SET status='assigned' WHERE id=?",[parsed.data.reportId]);
  await pool.query('INSERT INTO task_history(task_id,actor_user_id,action,to_status,notes) VALUES(?,?,?,?,?)',[result.insertId,request.authUser!.id,'assigned','assigned',parsed.data.description||null]);
  await pool.query("INSERT INTO notifications(user_id,type,title,body,data_json) VALUES(?,'task_assigned','New Task Assigned',?,?)",[parsed.data.assignedTo,`${reference}: ${parsed.data.title}`,JSON.stringify({taskId:result.insertId,reportId:parsed.data.reportId})]);
  await pool.query("INSERT INTO notifications(user_id,type,title,body,data_json) VALUES(?,'report_assigned','Your Report Has Been Assigned',?,?)",[reports[0].citizen_id,`${reference} has been assigned to a field team.`,JSON.stringify({taskId:result.insertId,reportId:parsed.data.reportId})]);
  await audit(request.authUser!.id,'task.assigned',request,'task',result.insertId,{reportId:parsed.data.reportId,assignedTo:parsed.data.assignedTo});
  response.status(201).json({data:{id:result.insertId,reference,...parsed.data,status:'assigned'}});
});

app.get('/api/support/tickets-scoped',authenticate,async(request,response)=>{
  const user=request.authUser!;
  const params:any[]=[];
  let scope='';
  if(user.role==='CITIZEN'){scope='WHERE t.opened_by=?';params.push(user.id);}
  else if(user.role==='STAFF'){scope='WHERE (t.assigned_to=? OR (t.assigned_to IS NULL AND opener.district_id=(SELECT district_id FROM users WHERE id=?)))';params.push(user.id,user.id);}
  else if(user.role==='SUPERVISOR'){scope='WHERE opener.district_id=(SELECT district_id FROM users WHERE id=?)';params.push(user.id);}
  const [rows]=await pool.query(`SELECT t.*,c.id conversation_id,opener.full_name opened_by_name,assignee.full_name assigned_to_name FROM support_tickets t LEFT JOIN conversations c ON c.ticket_id=t.id JOIN users opener ON opener.id=t.opened_by LEFT JOIN users assignee ON assignee.id=t.assigned_to ${scope} ORDER BY t.updated_at DESC`,params);
  response.json({data:rows});
});

app.post('/api/support/tickets-operational',authenticate,async(request,response)=>{
  const parsed=z.object({subject:z.string().min(3),category:z.string().min(2).default('general'),priority:z.enum(['low','medium','high','critical']).default('medium'),message:z.string().min(2)}).safeParse(request.body);
  if(!parsed.success)return response.status(422).json({error:'Invalid support request.'});
  const reference=`SUP-${new Date().getFullYear()}-${crypto.randomInt(100000,999999)}`,connection=await pool.getConnection();
  try{await connection.beginTransaction();const [ticket]=await connection.query<any>('INSERT INTO support_tickets(reference,opened_by,subject,category,priority) VALUES(?,?,?,?,?)',[reference,request.authUser!.id,parsed.data.subject,parsed.data.category,parsed.data.priority]);const [conversation]=await connection.query<any>('INSERT INTO conversations(ticket_id,subject,created_by) VALUES(?,?,?)',[ticket.insertId,parsed.data.subject,request.authUser!.id]);await connection.query('INSERT INTO conversation_participants(conversation_id,user_id) VALUES(?,?)',[conversation.insertId,request.authUser!.id]);await connection.query('INSERT INTO messages(conversation_id,sender_user_id,body) VALUES(?,?,?)',[conversation.insertId,request.authUser!.id,parsed.data.message]);await connection.query(`INSERT INTO notifications(user_id,type,title,body,data_json) SELECT u.id,'support_message','New Citizen Support Message',?,? FROM users u JOIN roles r ON r.id=u.role_id WHERE u.status='active' AND r.code IN ('STAFF','SUPERVISOR','ADMINISTRATOR') AND (r.code='ADMINISTRATOR' OR u.district_id=(SELECT district_id FROM users WHERE id=?))`,[`${reference}: ${parsed.data.subject}`,JSON.stringify({ticketId:ticket.insertId,conversationId:conversation.insertId}),request.authUser!.id]);await connection.commit();await audit(request.authUser!.id,'ticket.created',request,'support_ticket',ticket.insertId);response.status(201).json({data:{id:ticket.insertId,reference,conversationId:conversation.insertId,...parsed.data,status:'open'}});}catch(error){await connection.rollback();throw error;}finally{connection.release();}
});

app.post('/api/support/conversations/:id/messages-operational',authenticate,async(request,response)=>{
  const body=z.string().min(1).max(5000).safeParse(request.body?.body);if(!body.success)return response.status(422).json({error:'Message is required.'});
  const user=request.authUser!;const [access]=await pool.query<any[]>(`SELECT c.id,c.ticket_id,t.opened_by,t.assigned_to,opener.district_id FROM conversations c JOIN support_tickets t ON t.id=c.ticket_id JOIN users opener ON opener.id=t.opened_by WHERE c.id=? AND (t.opened_by=? OR t.assigned_to=? OR ?='ADMINISTRATOR' OR (?='SUPERVISOR' AND opener.district_id=(SELECT district_id FROM users WHERE id=?)) OR (?='STAFF' AND opener.district_id=(SELECT district_id FROM users WHERE id=?)))`,[request.params.id,user.id,user.id,user.role,user.role,user.id,user.role,user.id]);
  if(!access[0])return response.status(403).json({error:'Conversation access denied.'});
  await pool.query('INSERT IGNORE INTO conversation_participants(conversation_id,user_id) VALUES(?,?)',[request.params.id,user.id]);const [result]=await pool.query<any>('INSERT INTO messages(conversation_id,sender_user_id,body) VALUES(?,?,?)',[request.params.id,user.id,body.data]);await pool.query('UPDATE conversations SET updated_at=NOW() WHERE id=?',[request.params.id]);await pool.query(`INSERT INTO notifications(user_id,type,title,body,data_json) SELECT DISTINCT recipient,'support_reply','New Support Reply',?,? FROM (SELECT opened_by recipient FROM support_tickets WHERE id=? UNION SELECT assigned_to FROM support_tickets WHERE id=? UNION SELECT user_id FROM conversation_participants WHERE conversation_id=?) recipients WHERE recipient IS NOT NULL AND recipient<>?`,[body.data.slice(0,180),JSON.stringify({ticketId:access[0].ticket_id,conversationId:Number(request.params.id)}),access[0].ticket_id,access[0].ticket_id,request.params.id,user.id]);await audit(user.id,'message.sent',request,'message',result.insertId);response.status(201).json({data:{id:result.insertId,body:body.data}});
});

