app.post('/api/api-keys/rotate', authenticate, authorize('ADMINISTRATOR','NATIONAL_ADMIN'), async (request,response) => {
  const prefix='ecsl_live_';
  const rawKey=`${prefix}${crypto.randomBytes(32).toString('base64url')}`;
  const keyHash=crypto.createHash('sha256').update(rawKey).digest('hex');
  const connection=await pool.getConnection();
  try {
    await connection.beginTransaction();
    await connection.query('UPDATE api_keys SET revoked_at=NOW() WHERE owner_user_id=? AND revoked_at IS NULL',[request.authUser!.id]);
    const [result]=await connection.query<any>('INSERT INTO api_keys(owner_user_id,key_prefix,key_hash,last_four,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 1 YEAR))',[request.authUser!.id,prefix,keyHash,rawKey.slice(-4)]);
    await connection.commit();
    await audit(request.authUser!.id,'api_key.rotated',request,'api_key',result.insertId);
    response.status(201).json({data:{id:result.insertId,key:rawKey,maskedKey:`${prefix}••••••••${rawKey.slice(-4)}`,message:'Store this key securely. It will not be shown again.'}});
  } catch (error) {
    await connection.rollback();
    throw error;
  } finally { connection.release(); }
});

