app.get('/api/reports/export',authenticate,authorize('SUPERVISOR','ADMINISTRATOR','NATIONAL_ADMIN'),async(request,response)=>{const parsed=z.object({format:z.enum(['csv','pdf','json','geojson']).default('csv'),dateRange:z.enum(['all','today','week','quarter']).default('all'),status:z.string().max(40).optional(),priority:z.string().max(40).optional()}).safeParse(request.query);if(!parsed.success)return response.status(422).json({error:'Invalid export parameters.'});const where=['r.deleted_at IS NULL'],params:any[]=[];if(parsed.data.dateRange==='today')where.push('r.created_at>=DATE_SUB(NOW(),INTERVAL 1 DAY)');if(parsed.data.dateRange==='week')where.push('r.created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)');if(parsed.data.dateRange==='quarter')where.push('r.created_at>=DATE_SUB(NOW(),INTERVAL 3 MONTH)');if(parsed.data.status&&parsed.data.status!=='all'){where.push('r.status=?');params.push(parsed.data.status.toLowerCase().replace(/ /g,'_'));}if(parsed.data.priority&&parsed.data.priority!=='all'){where.push('r.priority=?');params.push(parsed.data.priority.toLowerCase());}if(request.authUser!.role==='SUPERVISOR'){const [scope]=await pool.query<any[]>('SELECT municipality_id,district_id FROM users WHERE id=?',[request.authUser!.id]);if(!scope[0]||(!scope[0].municipality_id&&!scope[0].district_id))return response.status(403).json({error:'Supervisor jurisdiction is not configured.'});where.push('(r.municipality_id=? OR r.district_id=?)');params.push(scope[0].municipality_id||0,scope[0].district_id||0);}const [rows]=await pool.query<any[]>(`SELECT r.reference,r.title,r.description,r.category,r.priority,r.status,r.latitude,r.longitude,r.address,r.created_at,r.updated_at,u.full_name citizen,u.email citizen_email,m.name municipality,d.name district,w.name ward,z.name zone FROM reports r JOIN users u ON u.id=r.citizen_id LEFT JOIN municipalities m ON m.id=r.municipality_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN wards w ON w.id=r.ward_id LEFT JOIN zones z ON z.id=r.zone_id WHERE ${where.join(' AND ')} ORDER BY r.created_at DESC`,params);const stamp=new Date().toISOString().slice(0,10),base=`ecoclean_reports_${stamp}`;await audit(request.authUser!.id,'reports.exported',request,'report',undefined,{format:parsed.data.format,dateRange:parsed.data.dateRange,records:rows.length});if(parsed.data.format==='json'){response.attachment(`${base}.json`).type('application/json').send(JSON.stringify({exportedAt:new Date().toISOString(),records:rows},null,2));return;}if(parsed.data.format==='geojson'){const features=rows.map(row=>({type:'Feature',geometry:{type:'Point',coordinates:[Number(row.longitude),Number(row.latitude)]},properties:Object.fromEntries(Object.entries(row).filter(([key])=>!['latitude','longitude'].includes(key)))}));response.attachment(`${base}.geojson`).type('application/geo+json').send(JSON.stringify({type:'FeatureCollection',features},null,2));return;}const headers=['Reference','Title','Description','Category','Priority','Status','Citizen','Citizen Email','Municipality','District','Ward','Zone','Latitude','Longitude','Address','Created','Updated'];const values=rows.map(row=>[row.reference,row.title,row.description,row.category,row.priority,row.status,row.citizen,row.citizen_email,row.municipality,row.district,row.ward,row.zone,row.latitude,row.longitude,row.address,row.created_at,row.updated_at]);if(parsed.data.format==='csv'){const csv='\uFEFF'+[headers,...values].map(record=>record.map(csvCell).join(',')).join('\r\n');response.attachment(`${base}.csv`).type('text/csv; charset=utf-8').send(csv);return;}const lines=values.map(record=>`${record[0]} | ${record[1]} | ${record[4]} | ${record[5]} | ${record[8]||record[9]||''} | ${new Date(record[15] as any).toLocaleDateString('en-SL')}`);response.attachment(`${base}.pdf`).type('application/pdf').send(createTextPdf('ECOCLEAN SL Incident Report Export',[headers.join(' | '),...lines]));});
