app.get('/api/support/tickets',authenticate,async(request,response)=>{const privileged=request.authUser!.role!=='CITIZEN';const [rows]=await pool.query(`SELECT t.*,c.id conversation_id,op.full_name opened_by_name,assignee.full_name assigned_to_name FROM support_tickets t LEFT JOIN conversations c ON c.ticket_id=t.id JOIN users op ON op.id=t.opened_by LEFT JOIN users assignee ON assignee.id=t.assigned_to ${privileged?'':'WHERE t.opened_by=? '}ORDER BY t.updated_at DESC`,privileged?[]:[request.authUser!.id]);response.json({data:rows});});
app.get('/api/support/metrics',authenticate,authorize('STAFF','SUPERVISOR','ADMINISTRATOR','NATIONAL_ADMIN'),async(_request,response)=>{const [summary]=await pool.query<any[]>('SELECT COUNT(*) total,SUM(status=\'open\') open,SUM(status=\'assigned\') assigned,SUM(status=\'escalated\') escalated,SUM(status IN (\'resolved\',\'closed\')) resolved,ROUND(AVG(CASE WHEN resolved_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,created_at,resolved_at) END),1) avg_resolution_minutes FROM support_tickets');const [staff]=await pool.query('SELECT u.id,u.full_name,COUNT(t.id) assigned,SUM(t.status IN (\'resolved\',\'closed\')) resolved FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN support_tickets t ON t.assigned_to=u.id WHERE r.code IN (\'STAFF\',\'SUPERVISOR\') GROUP BY u.id,u.full_name');response.json({data:{summary:summary[0],staff}});});
app.post('/api/support/tickets',authenticate,async(request,response)=>{const parsed=z.object({subject:z.string().min(3),category:z.string().min(2).default('general'),priority:z.enum(['low','medium','high','critical']).default('medium'),message:z.string().min(2)}).safeParse(request.body);if(!parsed.success)return response.status(422).json({error:'Invalid support request.'});const reference=`SUP-${new Date().getFullYear()}-${crypto.randomInt(100000,999999)}`;const connection=await pool.getConnection();try{await connection.beginTransaction();const [ticket]=await connection.query<any>('INSERT INTO support_tickets(reference,opened_by,subject,category,priority) VALUES(?,?,?,?,?)',[reference,request.authUser!.id,parsed.data.subject,parsed.data.category,parsed.data.priority]);const [conversation]=await connection.query<any>('INSERT INTO conversations(ticket_id,subject,created_by) VALUES(?,?,?)',[ticket.insertId,parsed.data.subject,request.authUser!.id]);await connection.query('INSERT INTO conversation_participants(conversation_id,user_id) VALUES(?,?)',[conversation.insertId,request.authUser!.id]);await connection.query('INSERT INTO messages(conversation_id,sender_user_id,body) VALUES(?,?,?)',[conversation.insertId,request.authUser!.id,parsed.data.message]);await connection.commit();await audit(request.authUser!.id,'ticket.created',request,'support_ticket',ticket.insertId);response.status(201).json({data:{id:ticket.insertId,reference,conversationId:conversation.insertId,...parsed.data,status:'open'}});}catch(error){await connection.rollback();throw error;}finally{connection.release();}});
app.patch('/api/support/tickets/:id',authenticate,authorize('STAFF','SUPERVISOR','ADMINISTRATOR','NATIONAL_ADMIN'),async(request,response)=>{const parsed=z.object({assignedTo:z.number().int().optional(),status:z.enum(['open','assigned','escalated','resolved','closed']).optional(),priority:z.enum(['low','medium','high','critical']).optional(),resolution:z.string().optional()}).safeParse(request.body);if(!parsed.success)return response.status(422).json({error:'Invalid ticket update.'});const mapping:any={assignedTo:'assigned_to',status:'status',priority:'priority',resolution:'resolution'};const fields=Object.keys(parsed.data);if(!fields.length)return response.status(422).json({error:'No update supplied.'});await pool.query(`UPDATE support_tickets SET ${fields.map(field=>`${mapping[field]}=?`).join(',')}${parsed.data.status==='resolved'?',resolved_at=NOW()':''} WHERE id=?`,[...Object.values(parsed.data),request.params.id]);await audit(request.authUser!.id,'ticket.updated',request,'support_ticket',Number(request.params.id),parsed.data);response.json({message:'Ticket updated.'});});
app.get('/api/support/conversations/:id/messages',authenticate,async(request,response)=>{const privileged=request.authUser!.role!=='CITIZEN';const [access]=await pool.query<any[]>('SELECT c.id FROM conversations c LEFT JOIN conversation_participants p ON p.conversation_id=c.id AND p.user_id=? WHERE c.id=? AND (? OR p.user_id IS NOT NULL)',[request.authUser!.id,request.params.id,privileged]);if(!access[0])return response.status(403).json({error:'Conversation access denied.'});const [rows]=await pool.query('SELECT m.*,u.full_name sender_name,r.code sender_role FROM messages m JOIN users u ON u.id=m.sender_user_id JOIN roles r ON r.id=u.role_id WHERE m.conversation_id=? AND m.deleted_at IS NULL ORDER BY m.created_at',[request.params.id]);response.json({data:rows});});
app.post('/api/support/conversations/:id/messages',authenticate,async(request,response)=>{const body=z.string().min(1).max(5000).safeParse(request.body?.body);if(!body.success)return response.status(422).json({error:'Message is required.'});const privileged=request.authUser!.role!=='CITIZEN';const [access]=await pool.query<any[]>('SELECT c.id,c.ticket_id FROM conversations c LEFT JOIN conversation_participants p ON p.conversation_id=c.id AND p.user_id=? WHERE c.id=? AND (? OR p.user_id IS NOT NULL)',[request.authUser!.id,request.params.id,privileged]);if(!access[0])return response.status(403).json({error:'Conversation access denied.'});if(privileged)await pool.query('INSERT IGNORE INTO conversation_participants(conversation_id,user_id) VALUES(?,?)',[request.params.id,request.authUser!.id]);const [result]=await pool.query<any>('INSERT INTO messages(conversation_id,sender_user_id,body) VALUES(?,?,?)',[request.params.id,request.authUser!.id,body.data]);await pool.query('UPDATE conversations SET updated_at=NOW() WHERE id=?',[request.params.id]);await audit(request.authUser!.id,'message.sent',request,'message',result.insertId);response.status(201).json({data:{id:result.insertId,body:body.data}});});

app.post('/api/uploads',authenticate,upload.array('files',5),async(request,response)=>{const purpose=z.enum(['report_evidence','task_evidence','profile_image','ticket_attachment']).safeParse(request.body?.purpose);if(!purpose.success||!request.files?.length)return response.status(422).json({error:'Valid purpose and files are required.'});if(purpose.data==='profile_image'&&request.files.length!==1)return response.status(422).json({error:'Upload exactly one profile image.'});const reportId=request.body.reportId?Number(request.body.reportId):null;const taskId=request.body.taskId?Number(request.body.taskId):null;const ticketId=request.body.ticketId?Number(request.body.ticketId):null;const privileged=['SUPERVISOR','ADMINISTRATOR','NATIONAL_ADMIN'].includes(request.authUser!.role);if(reportId){const [owned]=await pool.query<any[]>('SELECT id FROM reports WHERE id=? AND (? OR citizen_id=?)',[reportId,privileged,request.authUser!.id]);if(!owned[0])return response.status(403).json({error:'Report attachment ownership denied.'});}if(taskId){const [owned]=await pool.query<any[]>('SELECT id FROM tasks WHERE id=? AND (? OR assigned_to=?)',[taskId,privileged,request.authUser!.id]);if(!owned[0])return response.status(403).json({error:'Task attachment ownership denied.'});}if(ticketId){const [owned]=await pool.query<any[]>('SELECT id FROM support_tickets WHERE id=? AND (? OR opened_by=?)',[ticketId,request.authUser!.role!=='CITIZEN',request.authUser!.id]);if(!owned[0])return response.status(403).json({error:'Ticket attachment ownership denied.'});}const saved=[];for(const file of request.files as Express.Multer.File[]){if(purpose.data==='profile_image'&&!file.mimetype.startsWith('image/')){await fs.unlink(file.path);return response.status(422).json({error:'Profile photo must be an image.'});}const bytes=await fs.readFile(file.path);const signatures={png:bytes.subarray(0,8).toString('hex')==='89504e470d0a1a0a',jpg:bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff,webp:bytes.subarray(0,4).toString()==='RIFF'&&bytes.subarray(8,12).toString()==='WEBP',pdf:bytes.subarray(0,5).toString()==='%PDF-'};const signatureValid=(file.mimetype==='image/png'&&signatures.png)||(file.mimetype==='image/jpeg'&&signatures.jpg)||(file.mimetype==='image/webp'&&signatures.webp)||(file.mimetype==='application/pdf'&&signatures.pdf);if(!signatureValid){await fs.unlink(file.path);return response.status(422).json({error:`File signature does not match ${file.mimetype}.`});}const hash=crypto.createHash('sha256').update(bytes).digest('hex');const [result]=await pool.query<any>('INSERT INTO uploads(owner_user_id,report_id,task_id,ticket_id,purpose,original_name,stored_name,mime_type,size_bytes,sha256) VALUES(?,?,?,?,?,?,?,?,?,?)',[request.authUser!.id,reportId,taskId,ticketId,purpose.data,path.basename(file.originalname),file.filename,file.mimetype,file.size,hash]);await pool.query('INSERT INTO upload_scans(upload_id,status) VALUES(?,\'queued\')',[result.insertId]);if(purpose.data==='profile_image'){const [old]=await pool.query<any[]>('SELECT profile_upload_id FROM user_profiles WHERE user_id=?',[request.authUser!.id]);await pool.query('INSERT INTO user_profiles(user_id,profile_upload_id) VALUES(?,?) ON DUPLICATE KEY UPDATE profile_upload_id=VALUES(profile_upload_id)',[request.authUser!.id,result.insertId]);if(old[0]?.profile_upload_id)await pool.query('UPDATE uploads SET deleted_at=NOW(),replaced_by=? WHERE id=?',[result.insertId,old[0].profile_upload_id]);}saved.push({id:result.insertId,name:file.originalname,mimeType:file.mimetype,size:file.size,sha256:hash,scanStatus:'queued',url:`/api/uploads/${result.insertId}`});await audit(request.authUser!.id,'upload.created',request,'upload',result.insertId,{purpose:purpose.data,size:file.size,sha256:hash});}response.status(201).json({data:saved});});
app.get('/api/uploads/:id(\\d+)',authenticate,async(request,response)=>{const upload=await accessibleUpload(request.params.id,request.authUser!);if(!upload)return response.status(404).json({error:'Upload not found or access denied.'});const [scan]=await pool.query<any[]>("SELECT status FROM upload_scans WHERE upload_id=? ORDER BY id DESC LIMIT 1",[upload.id]);const scanStatus=scan[0]?.status||'unavailable';if(scanStatus==='infected')return response.status(423).json({error:'File is quarantined.'});if(config.requireCleanUploads&&scanStatus!=='clean')return response.status(423).json({error:'File is not available until malware scanning completes.',scanStatus});response.setHeader('Cache-Control','private, max-age=300');response.setHeader('Content-Disposition',`${request.query.download==='1'?'attachment':'inline'}; filename*=UTF-8''${encodeURIComponent(upload.original_name)}`);response.type(upload.mime_type).sendFile(path.join(uploadRoot,path.basename(upload.stored_name)));});

app.get('/api/system/settings',authenticate,authorize('ADMINISTRATOR','NATIONAL_ADMIN'),async(_request,response)=>{const [rows]=await pool.query<any[]>('SELECT setting_key,value_json,is_public,updated_at FROM system_settings');response.json({data:Object.fromEntries(rows.map(row=>[row.setting_key,typeof row.value_json==='string'?JSON.parse(row.value_json):row.value_json]))});});
app.put('/api/system/settings/:key',authenticate,authorize('NATIONAL_ADMIN'),async(request,response)=>{await pool.query('INSERT INTO system_settings(setting_key,value_json,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE value_json=VALUES(value_json),updated_by=VALUES(updated_by)',[request.params.key,JSON.stringify(request.body?.value??null),request.authUser!.id]);await audit(request.authUser!.id,'setting.updated',request,'system_setting',undefined,{key:request.params.key});response.status(204).end();});
app.get('/api/rbac',authenticate,authorize('ADMINISTRATOR','NATIONAL_ADMIN'),async(_request,response)=>{const [rows]=await pool.query('SELECT r.code role_code,r.name role_name,p.code permission_code,p.name permission_name FROM roles r LEFT JOIN role_permissions rp ON rp.role_id=r.id LEFT JOIN permissions p ON p.id=rp.permission_id ORDER BY r.id,p.code');response.json({data:rows});});
app.put('/api/rbac/:role/:permission',authenticate,authorize('NATIONAL_ADMIN'),async(request,response)=>{const enabled=z.boolean().safeParse(request.body?.enabled);if(!enabled.success)return response.status(422).json({error:'enabled must be boolean.'});if(enabled.data)await pool.query('INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r,permissions p WHERE r.code=? AND p.code=?',[request.params.role,request.params.permission]);else await pool.query('DELETE rp FROM role_permissions rp JOIN roles r ON r.id=rp.role_id JOIN permissions p ON p.id=rp.permission_id WHERE r.code=? AND p.code=?',[request.params.role,request.params.permission]);await audit(request.authUser!.id,'permission.changed',request,'role_permission',undefined,{...request.params,enabled:enabled.data});response.status(204).end();});
app.get('/api/dashboard',authenticate,async(request,response)=>{const role=request.authUser!.role;const userId=request.authUser!.id;const [[reports],[tasks],[notifications],[tickets]]=await Promise.all([pool.query<any[]>(`SELECT COUNT(*) total,SUM(status IN ('pending','under_review','assigned','in_progress')) open,SUM(status IN ('completed','verified','closed')) resolved FROM reports ${role==='CITIZEN'?'WHERE citizen_id=?':''}`,role==='CITIZEN'?[userId]:[]),pool.query<any[]>(`SELECT COUNT(*) total,SUM(status IN ('assigned','accepted','in_progress')) pending,SUM(status IN ('completed','verified')) completed FROM tasks ${role==='STAFF'?'WHERE assigned_to=?':''}`,role==='STAFF'?[userId]:[]),pool.query<any[]>('SELECT COUNT(*) total,SUM(read_at IS NULL) unread FROM notifications WHERE user_id=?',[userId]),pool.query<any[]>(`SELECT COUNT(*) total,SUM(status NOT IN ('resolved','closed')) open FROM support_tickets ${role==='CITIZEN'?'WHERE opened_by=?':''}`,role==='CITIZEN'?[userId]:[])]);response.json({data:{reports:reports[0],tasks:tasks[0],notifications:notifications[0],tickets:tickets[0]}});});

